{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "처방의 정확성이 의심될 때 투약을 강행하지 않고 확인을 위해 보류할 수 있는지 검증한다. 질문은 투약을 멈추기로 판단한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 처방에서 용량의 적절성을 의심하게 된 상황이 제시된다.",
          "task": "확인되지 않은 처방대로 투약하지 않도록 투약 진행 여부를 판단해야 했던 책임이 드러난다.",
          "action": "처방에서 발견한 이상과 비교한 정보를 바탕으로 투약을 보류한 이유를 설명한다.",
          "result": "의심이 해소되기 전 투약을 진행하지 않았다는 판단의 직접적인 결과가 드러난다."
        },
        "expectedEvidence": [
          "투약을 멈추기로 한 구체적인 판단 근거",
          "처방의 어떤 내용이 의심스러웠는지와 이를 판단할 때 비교한 정보",
          "처방이 확인되지 않은 상태에서 투약을 진행하면 안 된다고 본 이유"
        ]
      },
      "question": "푸른결종합병원에서 진통제 처방이 평소 용량의 두 배로 들어온 적이 있다고 하셨는데요, 그때 투약을 멈추기로 한 판단 근거는 무엇이었어요?",
      "answerTip": "당시 상황을 떠올리며 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "처방의 어떤 내용이 의심스러웠는지와 비교한 정보를 구체적으로 설명한다.",
            "평소와 다르다는 인상에 그치지 않고 처방 확인이 필요하다고 판단한 이유를 설명한다.",
            "의심이 해소되기 전에는 투약하지 않겠다는 판단과 실제 보류 행동의 연결이 명확하다."
          ]
        },
        "acceptable": {
          "criteria": [
            "용량 등 처방의 이상을 발견해 투약을 보류했다는 핵심 판단은 확인된다.",
            "다만 비교한 정보나 처방 확인이 필요하다고 본 이유가 충분히 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 멈춘 판단 근거를 제시하지 못하고 일반적인 투약 원칙만 설명한다.",
            "처방이 의심되어도 확인 없이 투약할 수 있다는 취지로 답하거나, 당시 판단과 무관한 내용에 머문다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "관찰한 환자 상태의 변화를 간호 기록에 정확히 남길 수 있는지 검증한다. 질문은 실제 기록에 담은 내용에 초점을 두며, 의사 보고나 인수인계 수행 여부는 이 질문의 필수 평가 대상으로 삼지 않는다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동에서 수술 후 환자의 상태 변화를 관찰한 사례가 제시된다.",
          "task": "관찰한 변화가 이후에도 정확히 확인될 수 있도록 간호 기록을 남겨야 했던 상황이 드러난다.",
          "action": "관찰 시점, 확인한 상태, 이전 상태와 달라진 점을 실제 기록 내용 중심으로 설명한다.",
          "result": "기록에 남긴 내용으로 환자의 상태 변화와 그 시점을 파악할 수 있다."
        },
        "expectedEvidence": [
          "선택한 환자 사례에서 실제 간호 기록에 남긴 구체적인 내용",
          "관찰 시점과 활력징후, 통증, 의식 수준 등 해당 사례에서 확인한 상태 정보",
          "이전 상태와 비교해 무엇이 달라졌는지 드러나는 기록 내용",
          "관찰한 사실과 추정을 혼동하지 않고 기록했다는 근거"
        ]
      },
      "question": "푸른결종합병원에서 활력징후와 통증 관찰 기록을 맡으셨던데요, 상태가 달라졌던 수술 후 환자 한 명의 간호 기록에는 어떤 내용을 남기셨어요?",
      "answerTip": "기억나는 한 사례를 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제 기록한 내용을 구체적으로 설명하며 관찰 시점과 해당 환자의 상태 정보가 확인된다.",
            "이전 상태와 달라진 점이 기록 내용에 드러나 환자의 변화 양상을 파악할 수 있다.",
            "관찰한 사실과 추정을 구분해 설명하며, 기록의 정확성을 뒷받침한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "환자 상태 변화와 관련해 실제 기록한 핵심 내용은 제시한다.",
            "다만 관찰 시점, 이전 상태와의 차이 또는 객관적인 상태 정보가 일부 부족해 변화 양상을 충분히 파악하기 어렵다."
          ]
        },
        "poor": {
          "criteria": [
            "실제 기록 내용 없이 간호 기록을 잘 작성했다는 주장이나 일반적인 작성 원칙만 제시한다.",
            "상태가 나빠졌다는 표현에 그쳐 어떤 변화가 있었는지 확인할 수 없거나, 추정을 관찰 사실처럼 설명한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P06",
  "interviews": [
    {
      "categoryId": "P06-C1",
      "itemId": "P06-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "잠재 거래처 담당자와의 첫 접촉을 제품 소개 기회로 전환할 수 있는지 확인한다. 통화를 끝내려는 담당자에게 첫 미팅을 제안하는 실제 발화에 초점을 둔다.",
        "questionType": "situational",
        "expectedSTAR": {
          "situation": "신규 거래처 후보의 구매 담당자와 처음 전화가 연결됐지만 담당자가 바쁘다며 통화를 끝내려는 상황이다.",
          "task": "담당자의 시간 부담을 존중하면서 제품 소개를 위한 첫 미팅을 제안해야 한다.",
          "action": "짧은 통화 안에서 만나 볼 만한 업무상 이유를 전달하고, 담당자가 수락 여부를 답할 수 있도록 미팅을 제안한다.",
          "result": "담당자가 미팅의 목적과 부담을 이해하고 제안을 검토할 수 있다. 실제 미팅 성사 실적이 아닌 제안으로 기대하는 반응을 확인한다."
        },
        "expectedEvidence": [
          "담당자에게 실제로 전달할 첫 미팅 제안 문구",
          "단순한 인사나 회사 소개를 넘어 담당자가 제품 소개를 들어 볼 만한 이유",
          "바쁘다는 반응을 존중하면서 미팅 수락 여부를 답할 수 있게 하는 제안 방식"
        ]
      },
      "question": "신규 거래처 후보의 구매 담당자와 처음 전화가 연결됐는데, 바쁘다며 통화를 끝내려는 상황이라고 해 볼게요. 그때 첫 미팅을 제안하는 말은 어떻게 하시겠어요?",
      "answerTip": "실제 대화 장면을 떠올려 답해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "담당자에게 바로 사용할 수 있는 구체적인 미팅 제안 문구를 제시한다.",
            "담당자가 시간을 내어 제품 소개를 들어 볼 만한 업무상 이유가 제안에 드러난다.",
            "바쁘다는 반응을 존중하면서도 미팅 수락 여부를 답할 수 있는 명확한 제안으로 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "첫 미팅을 요청하는 말은 제시하지만 만남의 이유나 요청 내용이 다소 막연하다.",
            "담당자의 시간 부담을 인정하지만 회사 소개에 치우치거나 미팅 제안이 불분명하다."
          ]
        },
        "poor": {
          "criteria": [
            "실제로 전달할 말 없이 친절하게 설득하겠다는 태도만 설명한다.",
            "통화를 끝내거나 자료만 보내겠다고 할 뿐 첫 미팅을 제안하지 않는다.",
            "담당자의 반응과 무관하게 일방적으로 만남을 강요한다."
          ]
        }
      }
    },
    {
      "categoryId": "P06-C1",
      "itemId": "P06-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "기존 거래처의 발주 감소 원인에 맞춰 거래를 유지할 대안을 제안할 수 있는지 확인한다. 납기 불안으로 발주를 줄인 담당자에게 제시할 대안 하나에 초점을 둔다.",
        "questionType": "situational",
        "expectedSTAR": {
          "situation": "기존 거래처 담당자가 납기 불안 때문에 발주를 줄였다고 밝힌 상황이다.",
          "task": "확인된 불만에 대응해 거래를 이어 갈 수 있는 대안을 제안해야 한다.",
          "action": "납기 불안이 거래처의 발주에 미치는 부담을 줄이는 구체적인 거래 대안을 담당자에게 제안한다.",
          "result": "담당자가 기존 거래를 유지하거나 발주를 재검토할 만한 이유를 얻는다. 실제 발주 회복 실적이나 실행 이후의 측정은 요구하지 않는다."
        },
        "expectedEvidence": [
          "담당자에게 제안할 구체적인 거래 유지 대안 하나",
          "제안한 대안이 발주 감소 원인인 납기 불안에 대응하는 방식",
          "그 대안이 거래처의 거래 지속 판단에 도움이 되는 이유"
        ]
      },
      "question": "기존 거래처 담당자가 납기 불안 때문에 발주를 줄였다고 말한 상황이라고 해 볼게요. 그때 담당자에게 거래를 이어 가기 위한 대안으로 무엇을 제안하시겠어요?",
      "answerTip": "한 가지 선택을 중심으로 답해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "담당자가 검토할 수 있는 구체적인 거래 유지 대안을 제시한다.",
            "대안이 납기 불안으로 인한 거래처의 부담을 줄이는 방식이 분명하다.",
            "해당 대안이 거래를 이어 갈 이유가 되는지를 상황에 맞게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "납기 불안에 대응하는 대안을 제시하지만 내용이 포괄적이거나 구체성이 부족하다.",
            "거래 유지에 도움이 될 방향은 드러나지만 거래처의 부담을 줄이는 방식이 충분히 설명되지 않는다."
          ]
        },
        "poor": {
          "criteria": [
            "잘 관리하겠다는 다짐이나 사과만 제시하고 거래 유지 대안을 말하지 않는다.",
            "납기 불안과 관련 없는 제품 홍보나 발주 요청만 반복한다.",
            "제시한 대안이 거래처가 발주를 줄인 이유에 대응하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P12",
  "interviews": [
    {
      "categoryId": "P12-C1",
      "itemId": "P12-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "막연한 펌프 구매 요구를 사양 협의에 필요한 조건으로 구체화할 수 있는지 검증한다. 고객에게 처음 던질 질문을 선택하는 데 초점을 둔다.",
        "questionType": "situational",
        "expectedSTAR": {
          "situation": "고객이 물을 많이 보내는 펌프의 견적을 요청했으나 필요한 성능과 설치 조건이 확인되지 않은 상황이다.",
          "task": "사양 선정에 영향을 주는 고객의 요구나 현장 조건을 확인할 첫 질문을 정한다.",
          "action": "고객이 답할 수 있는 표현으로 필요한 유량이나 물을 보내는 높이 등 사양을 가르는 조건 하나를 묻는다.",
          "result": "고객의 답변을 통해 막연한 요청을 구체적인 사양 조건으로 좁힐 수 있다. 실제 견적 작성이나 협의 완료까지 제시할 필요는 없다."
        },
        "expectedEvidence": [
          "고객에게 가장 먼저 할 구체적인 질문 한 가지",
          "그 질문이 고객의 사용 목적이나 현장 조건 중 어떤 불확실성을 해소하는지에 대한 설명",
          "예상되는 고객의 답변이 필요한 펌프 사양을 좁히는 데 어떻게 쓰이는지에 대한 연결"
        ]
      },
      "question": "고객이 물을 많이 보내는 펌프로 견적을 달라고 하는데, 현장 정보는 없는 상황이라고 해 볼게요. 그때 고객에게 가장 먼저 할 질문은 무엇이겠어요?",
      "answerTip": "장면을 떠올리며 차분히 답해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "고객이 이해하고 답할 수 있는 구체적인 첫 질문을 제시한다.",
            "질문이 필요한 유량이나 이송 높이 등 펌프 사양에 직접 영향을 주는 불확실성을 겨냥한다.",
            "해당 질문의 답변으로 어떤 사양 조건을 좁힐 수 있는지 타당하게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "고객의 요구나 현장 조건을 확인하는 관련 질문을 제시한다.",
            "다만 질문의 표현이 포괄적이거나, 답변이 사양 구체화에 쓰이는 연결이 충분히 드러나지 않는다."
          ]
        },
        "poor": {
          "criteria": [
            "고객에게 실제로 할 질문을 제시하지 않고 요구사항을 확인하겠다는 원론적인 답변에 그친다.",
            "또는 사양에 영향을 주는 요구와 현장 조건을 확인하지 않은 채 특정 제품이나 견적을 제시한다."
          ]
        }
      }
    },
    {
      "categoryId": "P12-C1",
      "itemId": "P12-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "원심 펌프의 카탈로그 성능과 현장 성능의 관계를 비전공 고객에게 이해 가능한 말로 전달할 수 있는지 검증한다. 현장 유량이 달라질 수 있는 이유를 고객에게 직접 설명하는 데 초점을 둔다.",
        "questionType": "situational",
